package com.rpb.reservation.workforce;
import static org.assertj.core.api.Assertions.*;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import com.rpb.reservation.workforce.application.WorkforceJson;
import com.rpb.reservation.workforce.payroll.governance.EffectivePayGovernance;
import com.rpb.reservation.workforce.statutory.StatutoryDtos.CpfProfile;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.*;import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
class WorkforcePayGovernanceMigrationPostgresTest extends WorkforcePostgresTest {
 @Test void actualInstallationRetainsFutureProfilesAndMonthlyInputsWithoutRewritingSnapshots()throws Exception{
  UUID employee=UUID.randomUUID();employees.save(admin,store,employee,command(0,List.of(store),company,null,null));
  String schema="wf_pay_mig_"+UUID.randomUUID().toString().replace("-","");var pointer=new HashMap<String,String>();for(var line:Files.readAllLines(Path.of("target/local-postgres-current.txt"))){var parts=line.split("=",2);if(parts.length==2)pointer.put(parts[0],parts[1]);}assertThat(Path.of(pointer.get("runtimeWorktree")).toAbsolutePath()).isEqualTo(Path.of("").toAbsolutePath());
  root.execute("create schema "+schema);var db=new JdbcTemplate(new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:"+Integer.parseInt(pointer.get("port"))+"/postgres?stringtype=unspecified&currentSchema="+schema,"postgres",""));var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());
  try{
   try(var files=Files.list(Path.of("src/main/resources/db/migration"))){for(var file:files.filter(p->p.getFileName().toString().matches("V\\d+__.*\\.sql")).sorted().toList()){int version=Integer.parseInt(file.getFileName().toString().split("__",2)[0].substring(1));if(version<110)db.execute(Files.readString(file));}}
   for(var table:List.of("tenants","operating_entities","stores","auth_accounts","workforce_positions","workforce_employees")){String condition=table.equals("tenants")?"id":"tenant_id";db.execute("insert into "+table+" select * from "+SCHEMA+"."+table+" where "+condition+"='"+tenant+"'");}
   var rule=new Rule("monthly","3000.00","8.00","44.00",false,"1.50",List.of(),new Generation("fixed",List.of()));UUID template=UUID.randomUUID();var t=new SalaryTemplate(template,company,"Installed",rule,true,1);db.update("insert into workforce_pay_templates(id,tenant_id,company_id,name,snapshot,enabled,version) values(?,?,?,'Installed',?::jsonb,true,1)",template,tenant,company,json.write(t));
   var future=new PayProfile(UUID.randomUUID(),company,employee,"Alice",LocalDate.of(2027,1,1),template,1,rule,new CpfProfile("foreign",null,null,"GG",""),1);db.update("insert into workforce_pay_profiles(id,tenant_id,company_id,employee_id,effective_from,template_id,template_version,version,snapshot) values(?,?,?,?,?,?,1,1,?::jsonb)",future.id(),tenant,company,employee,future.effectiveFrom(),template,json.write(future));
   UUID active=UUID.randomUUID();seed(db,json,active,employee,"2026-11","draft","90.00");seed(db,json,UUID.randomUUID(),employee,"2026-10","voided","10.00");seed(db,json,UUID.randomUUID(),employee,"2026-10","voided","20.00");seed(db,json,UUID.randomUUID(),employee,"2026-11","voided","999.00");seed(db,json,UUID.randomUUID(),employee,"2026-12","voided","25.00");seed(db,json,UUID.randomUUID(),employee,"2027-01","voided","45.00");UUID identical=UUID.randomUUID();seed(db,json,identical,employee,"2027-01","voided","45.00");db.update("update workforce_pay_inputs set snapshot=jsonb_set(snapshot,'{cdacReview}','null'::jsonb) where batch_id=?",identical);
   UUID frozen=UUID.randomUUID();String snapshot="{\"sourceFingerprint\":\"frozen-original\",\"lines\":[]}";db.update("insert into workforce_pay_batches(id,tenant_id,company_id,company_name,period_month,status,version,calculation,created_by,confirmed_by,confirmed_at,published_by,published_at) values(?,?,?,'Company','2026-09-01','published',1,?::jsonb,?,?,now(),?,now())",frozen,tenant,company,snapshot,adminId,adminId,adminId);
   String beforeProfile=db.queryForObject("select snapshot::text from workforce_pay_profiles where id=?",String.class,future.id()),beforeInput=db.queryForObject("select snapshot::text from workforce_pay_inputs where batch_id=?",String.class,active),beforeFrozen=db.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,frozen);
   var effective=new EffectivePayGovernance(db,json);assertThatThrownBy(()->effective.assertProfile(tenant,future)).isInstanceOf(org.springframework.dao.DataAccessException.class);
   db.execute(Files.readString(Path.of("src/main/resources/db/migration/V110__workforce_effective_pay_evidence.sql")));
   var evidence=effective.evidence(tenant,company,"profile",future.id(),null,1,future);assertThat(evidence.kind()).isEqualTo("legacy-valid");assertThat(evidence.requestId()).isNull();effective.assertProfile(tenant,future);
   assertThat(effective.monthly(tenant,company,employee,YearMonth.of(2026,11)).input().items().getFirst().amount()).isEqualTo("90.00");assertThat(effective.monthly(tenant,company,employee,YearMonth.of(2026,10)).issue()).isEqualTo("WORKFORCE_PAYROLL_INPUT_AMBIGUOUS");assertThat(effective.monthly(tenant,company,employee,YearMonth.of(2026,12)).input().items()).extracting(Item::amount).containsExactly("25.00");assertThat(effective.monthly(tenant,company,employee,YearMonth.of(2027,1)).input().items()).extracting(Item::amount).containsExactly("45.00");
   assertThat(db.queryForObject("select count(*) from workforce_pay_change_requests",Integer.class)).isZero();assertThat(db.queryForObject("select snapshot::text from workforce_pay_profiles where id=?",String.class,future.id())).isEqualTo(beforeProfile);assertThat(db.queryForObject("select snapshot::text from workforce_pay_inputs where batch_id=?",String.class,active)).isEqualTo(beforeInput);assertThat(db.queryForObject("select calculation::text from workforce_pay_batches where id=?",String.class,frozen)).isEqualTo(beforeFrozen);
  }finally{if(schema.matches("wf_pay_mig_[a-f0-9]{32}"))root.execute("drop schema "+schema+" cascade");}
 }
 void seed(JdbcTemplate db,WorkforceJson json,UUID batch,UUID employee,String month,String status,String amount){db.update("insert into workforce_pay_batches(id,tenant_id,company_id,company_name,period_month,status,version,created_by) values(?,?,?,'Company',?,?,1,?)",batch,tenant,company,YearMonth.parse(month).atDay(1),status,adminId);var input=new LineInput(employee,1,null,null,true,false,List.of(new Item("Installed adjustment","ow_allowance",amount)),"Installed facts");db.update("insert into workforce_pay_inputs(batch_id,tenant_id,company_id,employee_id,version,snapshot) values(?,?,?,?,1,?::jsonb)",batch,tenant,company,employee,json.write(input));}
}
